        `;
    },

    async confirmAndSend(proposal) {
        const content = document.getElementById('screen-content');
        if (!content) return;

        // Generate a secure dispute code
        const disputeCode = "LIT-" + Math.floor(1000 + Math.random() * 9000) + "-" + new Date().getFullYear();

        content.innerHTML = `
